code_block:
    name: 📊 Final Dashboard
    runs-on: ubuntu-latest
    needs:
      - ai-remediation-engine
      - sca-trivy
      - sca-owasp-dependency-check
      - sast-codeql
      - compliance-validation
    if: always()
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4

      - name: Setup Python
        uses: actions/setup-python@v5
        with:
          python-version: ${{ env.PYTHON_VERSION }}
          cache: pip

      - name: Create Reports Directory
        run: mkdir -p ${{ env.REPORTS_DIR }} ${{ env.DASHBOARD_DIR }}

      - name: Download All Report Artifacts
        uses: actions/download-artifact@v4
        with:
          pattern: '*-reports'
          path: ${{ env.REPORTS_DIR }}
          merge-multiple: true
        continue-on-error: true

      - name: Download AI Artifacts
        uses: actions/download-artifact@v4
        with:
          pattern: ai-*-report
          path: ${{ env.REPORTS_DIR }}
          merge-multiple: true
        continue-on-error: true

      - name: Download Existing Dashboard State
        uses: actions/download-artifact@v4
        with:
          name: dashboard-state
          path: ${{ env.DASHBOARD_DIR }}
        continue-on-error: true

      - name: Final Aggregation with All Job Results
        env:
          STAGE_NAME: "final-dashboard"
          STAGE_LABEL: "Pipeline Complete"
          STAGE_ICON: "📊"
          JOB_STATUS: ${{ job.status }}
          RUN_ID: ${{ github.run_id }}
          COMMIT: ${{ github.sha }}
          BRANCH: ${{ github.ref_name }}
          ACTOR: ${{ github.actor }}
          REPORTS_DIR: ${{ env.REPORTS_DIR }}
          PIPELINE_COMPLETE: "true"
          # Pass all job results for final status table
          R_SECRET:      ${{ needs.secret-detection.result           || 'skipped' }}
          R_PMD:         ${{ needs.sast-pmd-apex.result              || 'skipped' }}
          R_CODEQL:      ${{ needs.sast-codeql.result                || 'skipped' }}
          R_SF_SCANNER:  ${{ needs.sast-salesforce-scanner.result    || 'skipped' }}
          R_NPM:         ${{ needs.sca-npm-audit.result              || 'skipped' }}
          R_OWASP:       ${{ needs.sca-owasp-dependency-check.result || 'skipped' }}
          R_TRIVY:       ${{ needs.sca-trivy.result                  || 'skipped' }}
          R_AI_INTEL:    ${{ needs.ai-vulnerability-intelligence.result || 'skipped' }}
          R_SONAR:       ${{ needs.sonarqube-governance.result       || 'skipped' }}
          R_ORG_SEC:     ${{ needs.salesforce-org-security.result    || 'skipped' }}
          R_CHECKOV:     ${{ needs.compliance-checkov.result         || 'skipped' }}
          R_COMPLIANCE:  ${{ needs.compliance-validation.result      || 'skipped' }}
          R_REMEDIATION: ${{ needs.ai-remediation-engine.result      || 'skipped' }}
        run: python3 .github/scripts/update-dashboard.py

      - name: Validate Dashboard Files
        run: |
          ls -lh ${{ env.DASHBOARD_DIR }}/
          [ -f "${{ env.DASHBOARD_DIR }}/index.html" ]          || { echo "::error::index.html missing from dashboard/"; exit 1; }
          [ -f "${{ env.DASHBOARD_DIR }}/dashboard-data.json" ] || { echo "::error::dashboard-data.json missing"; exit 1; }

      - name: Upload Final Dashboard Artifact
        uses: actions/upload-artifact@v4
        with:
          name: enterprise-dashboard-final
          path: |
            ${{ env.DASHBOARD_DIR }}/index.html
            ${{ env.DASHBOARD_DIR }}/dashboard-data.json
          overwrite: true

      - name: Deploy Final Dashboard to GitHub Pages
        uses: peaceiris/actions-gh-pages@v4
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          publish_dir: ${{ env.DASHBOARD_DIR }}
          keep_files: false
          commit_message: "dashboard: FINAL run=${{ github.run_id }} commit=${{ github.sha }}"

# =========================================================
# STAGE 11 — GMAIL NOTIFICATION (REST API — no SMTP)
# =========================================================

  gmail-notification:
    name: 📧 Gmail Notification

