- name: Post AI Summary to PR
  if: github.event_name == 'pull_request'
  uses: actions/github-script@v7
  with:
    script: |
      const fs = require('fs');
      let body = '## 🧠 AI Security Remediation Report\n\n';
      try {
        const r = JSON.parse(fs.readFileSync('${{ env.REPORTS_DIR }}/ai-remediation.json', 'utf8'));
        body += r.summary || 'Analysis complete. See workflow artifact for details.';
      } catch(e) {
        body += 'Remediation report generated — download workflow artifact for details.';
      }
      github.rest.issues.createComment({
        issue_number: context.issue.number,
        owner: context.repo.owner,
        repo: context.repo.repo,
        body
      });
  continue-on-error: true

- name: Upload AI Remediation Report
  uses: actions/upload-artifact@v4

- name: Push Stage Status to Dashboard
  if: always()
  env:
    STAGE_NAME: "ai-remediation-engine"
    STAGE_LABEL: "AI Remediation"
    STAGE_ICON: "🧠"
    JOB_STATUS: ${{ job.status }}
    RUN_ID: ${{ github.run_id }}
    COMMIT: ${{ github.sha }}
    BRANCH: ${{ github.ref_name }}
    ACTOR: ${{ github.actor }}
    REPORTS_DIR: ${{ env.REPORTS_DIR }}
  run: python3 .github/scripts/update-dashboard.py
  continue-on-error: true

- name: Deploy Partial Dashboard
  if: always()

- name: Final Aggregation with All Job Results
  env:
    STAGE_NAME: "final-dashboard"
    STAGE_LABEL: "Pipeline Complete"
    STAGE_ICON: "📊"
    JOB_STATUS: ${{ job.status }}
    RUN_ID: ${{ github.run_id }}
    COMMIT: ${{ github.sha }}
    BRANCH: ${{ github.ref_name }}
    ACTOR: ${{ github.actor }}
    REPORTS_DIR: ${{ env.REPORTS_DIR }}
    PIPELINE_COMPLETE: "true"
    # Pass all job results for final status table
    R_SECRET:      ${{ needs.secret-detection.result           || 'skipped' }}
    R_PMD:         ${{ needs.sast-pmd-apex.result              || 'skipped' }}
    R_CODEQL:      ${{ needs.sast-codeql.result                || 'skipped' }}
    R_SF_SCANNER:  ${{ needs.sast-salesforce-scanner.result    || 'skipped' }}
    R_NPM:         ${{ needs.sca-npm-audit.result              || 'skipped' }}
    R_OWASP:       ${{ needs.sca-owasp-dependency-check.result || 'skipped' }}
    R_TRIVY:       ${{ needs.sca-trivy.result                  || 'skipped' }}
    R_AI_INTEL:    ${{ needs.ai-vulnerability-intelligence.result || 'skipped' }}
    R_SONAR:       ${{ needs.sonarqube-governance.result       || 'skipped' }}
    R_ORG_SEC:     ${{ needs.salesforce-org-security.result    || 'skipped' }}
    R_CHECKOV:     ${{ needs.compliance-checkov.result         || 'skipped' }}
    R_COMPLIANCE:  ${{ needs.compliance-validation.result      || 'skipped' }}
    R_REMEDIATION: ${{ needs.ai-remediation-engine.result      || 'skipped' }}
  run: python3 .github/scripts/update-dashboard.py

- name: Validate Dashboard Files
  run: |

